  return el("text", {x: x, y: y, "font-size": size, "font-weight": weight, fill: fill, "text-anchor": anchor, "font-family": FF}, s);
}
function fmt(v){ return String(Math.round(v)).replace(/\B(?=(\d{3})+(?!\d))/g, "\u00a0"); }
var data = [{d:"31 août",v:36270.5},{d:"1 sept.",v:35825.7},{d:"2 sept.",v:36091.6},{d:"3 sept.",v:36633.1},{d:"4 sept.",v:36513.8},{d:"8 sept.",v:36123.1},{d:"9 sept.",v:35906.6},{d:"10 sept.",v:35506.3},{d:"11 sept.",v:35697.5},{d:"14 sept.",v:35702.5},{d:"15 sept.",v:35582.1},{d:"16 sept.",v:35491.3},{d:"17 sept.",v:35874.3},{d:"18 sept.",v:35806.7},{d:"21 sept.",v:36009.4},{d:"22 sept.",v:36335.6},{d:"23 sept.",v:35751.4},{d:"24 sept.",v:35706.5},{d:"25 sept.",v:35800.9},{d:"28 sept.",v:35489.9},{d:"29 sept.",v:35460.3},{d:"30 sept.",v:35235.9},{d:"1 oct.",v:35154.8},{d:"2 oct.",v:35502.7},{d:"5 oct.",v:35518.6},{d:"6 oct.",v:35649.5},{d:"7 oct.",v:35041.9},{d:"8 oct.",v:35145.4},{d:"9 oct.",v:35664.6},{d:"13 oct.",v:35984.0},{d:"14 oct.",v:35584.46}];
var n = data.length;
var margin = {left: 62, right: 24, top: 18, bottom: 46};
var PW = 594, PH = 236, MT = margin.top;
var vals = data.map(function(p){ return p.v; });
var lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
var pad = (hi - lo) * 0.12;
var yMin = Math.floor((lo - pad) / 200) * 200, yMax = Math.ceil((hi + pad) / 200) * 200;
function xp(i){ return margin.left + (i / (n - 1)) * PW; }
function yp(v){ return MT + (1 - (v - yMin) / (yMax - yMin)) * PH; }
var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("viewBox", "0 0 680 300");
svg.setAttribute("width", "100%");
var t;
for (t = yMin; t <= yMax; t += 400) {
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5}));
}
var refY = yp(data[0].v);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
var d = "";
data.forEach(function(p, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(p.v).toFixed(1) + " "; });
svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 1.8, "stroke-linejoin": "round"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var events = [
  {i: 23, l1: "2 OCT. EMPL. US", l2: "TSX +0,99\u00a0%", row: 0},
  {i: 28, l1: "9 OCT. EMPL. CAN.", l2: "TSX +1,48\u00a0%", row: 1},
  {i: 30, l1: "14 OCT. IPC US", l2: "TSX -1,11\u00a0%", row: 2}
];
events.forEach(function(ev){
  var ex = xp(ev.i);
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
});
var lastX = xp(n - 1), lastY = yp(data[n - 1].v);
svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));
var pillText = "35\u00a0584,46";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY + 8;
if (pillX < margin.left) pillX = margin.left;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 3.5, 9, 700, "#111111", "middle"));
events.forEach(function(ev){
  var ex = xp(ev.i);
  var w = Math.max(ev.l1.length, ev.l2.length) * 7 * 0.68;
  var nearRight = (ex + w + 3) > (margin.left + PW);
  var anchor = nearRight ? "end" : "start";
  var dx = nearRight ? -4 : 3;
  var y0 = MT + 8 + ev.row * 20;
  var hx = (anchor === "end") ? (ex + dx - w - 2) : (ex + dx - 2);
  svg.appendChild(el("rect", {x: hx, y: y0 - 8, width: w + 4, height: 20, fill: "#ffffff", "fill-opacity": 0.92}));
  svg.appendChild(tx(ev.l1, ex + dx, y0, 7, 700, "#1a3560", anchor));
  svg.appendChild(tx(ev.l2, ex + dx, y0 + 9, 7, 700, "#1a3560", anchor));
});
for (t = yMin; t <= yMax; t += 400) {
  svg.appendChild(tx(fmt(t), margin.left - 6, yp(t) + 3, 8.5, 400, "#aaaaaa", "end"));
}
[0, 5, 10, 15, 20, 25, 30].forEach(function(i){
  var a = (i === n - 1) ? "end" : "middle";
  svg.appendChild(tx(data[i].d, xp(i), MT + PH + 14, 8, 400, "#999999", a));
});
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Groupe TMX, clôtures quotidiennes de l’indice composé S&amp;P/TSX d’après Yahoo Finance, 31 août au 14 oct. 2026&nbsp;; calcul HDQ. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">La ligne verte en pointillé indique la clôture du 31 août, soit 36&nbsp;270,50. Les variations quotidiennes additionnées sans égard à leur direction totalisent 21,2 points de pourcentage, contre une variation nette de moins 1,9&nbsp;%.</p><h2>Ce que les deux prochaines publications régleront ou non</h2><p>Deux autres petits échantillons arrivent avant les décisions. Statistique Canada publiera les prix à la consommation de septembre le 19 octobre, et Continuum Economics s’attend à ce que l’inflation globale se maintienne à 3,0&nbsp;% pour un troisième mois, les mesures de l’inflation fondamentale de la Banque du Canada fléchissant légèrement. La Réserve fédérale et la Banque du Canada annonceront ensuite toutes deux leurs décisions le 28 octobre, le taux cible du financement à un jour canadien se situant à 2,25&nbsp;%, selon la Banque du Canada.</p><p>Les prévisionnistes professionnels ne s’entendent pas sur l’issue. Services économiques TD s’attend à un maintien du taux par la Banque du Canada en octobre, CIBC prévoit un maintien aux deux réunions restantes de 2026, et Capital Economics prévoit une hausse prochaine à 2,75&nbsp;%, le milieu de la fourchette neutre. Un tel écart en dit long sur la taille de l’échantillon&nbsp;: des économistes disposant de modèles complets et de longs historiques de données sont encore en désaccord après une publication de plus.</p><p>L’argument comportemental est limité. Chacune de ces publications est instructive et aucune n’est concluante. Les séances des 9 et 14 octobre ont fait monter l’indice de 1,48&nbsp;% puis baisser de 1,11&nbsp;% sur des publications qui touchaient la même question de politique monétaire, alors que les deux décisions des banques centrales étaient encore à 13 jours.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui suivent de près les manchettes ressentent davantage un effet de va-et-vient que de la crainte. Une remontée sur de mauvaises nouvelles de l’emploi au Canada le 9 octobre et une baisse sur de fortes nouvelles d’inflation américaine le 14 octobre semblent se contredire, et plusieurs se demandent laquelle croire. Les clients qui détiennent beaucoup d’énergie ressentent un soulagement teinté d’inquiétude, parce que le FNB du secteur de l’énergie XEG a terminé la séance du 14 octobre inchangé à 30,55&nbsp;$ alors que le FNB des minières aurifères XGD a reculé de 4,2&nbsp;%. Les clients exposés aux minières aurifères sont frustrés. Les clients dont le portefeuille est équilibré constatent que l’indice n’a nulle part progressé et veulent savoir pourquoi le parcours a été si cahoteux.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Je veux vous donner le portrait des six dernières semaines, et pas seulement des deux derniers jours. Depuis le 1er septembre, le TSX a connu 11 journées où il a varié d’environ un pour cent ou plus dans un sens ou dans l’autre, et il est en baisse de 1,9&nbsp;% sur cette période. C’est beaucoup de mouvement pour un si mince résultat net. Plusieurs de ces journées ont suivi une seule publication de données&nbsp;: un rapport sur l’emploi aux États-Unis, un rapport sur l’emploi au Canada, un rapport sur l’inflation aux États-Unis. Chacune a changé l’hypothèse du marché quant à une hausse de taux par la Réserve fédérale ou par la Banque du Canada le 28 octobre, et chaque hypothèse s’est inversée en quelques jours. Votre plan ne reposait sur aucune de ces hypothèses. Les prochaines publications sont l’inflation canadienne le 19 octobre et les deux décisions des banques centrales le 28 octobre, et je m’attends à plus de mouvement autour de ces dates. Ce que je propose, c’est de confirmer que votre plan répond toujours à vos besoins de revenu et à votre horizon de placement, et de le laisser en place à moins que l’un des deux n’ait changé. Pouvons-nous réserver quinze minutes la semaine du 19 octobre pour l’examiner ensemble&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients qui consultent leur solde chaque jour ou réagissent aux alertes de nouvelles, les retraités qui ont un retrait prévu avant le 28 octobre, et les clients qui ont déjà téléphoné ou écrit par courriel depuis le 9 octobre pour demander s’il fallait changer quelque chose.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients qui détiennent à la fois de l’énergie et des minières aurifères, qui ont vu des mouvements compensatoires le 14 octobre, et les clients à portefeuille équilibré dont l’exposition à l’indice est à peu près stable depuis la fin d’août.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients dont des liquidités attendent d’être investies selon un calendrier, qui ne sont pas des vendeurs forcés et peuvent voir dans ces fluctuations une raison de maintenir le calendrier.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste de tous les clients qui ont communiqué avec vous depuis le 9 octobre et noter si le contact a suivi une manchette ou une publication de données.</div>
<div class="checklist-item">Repérer les clients dont des retraits ou des cotisations sont prévus avant le 28 octobre et confirmer la source de financement de chacun.</div>
<div class="checklist-item">Inscrire au calendrier les contacts du 19 et du 28 octobre afin que les appels aient lieu avant les publications, et non après.</div>
<div class="checklist-item">Sortir le plus récent questionnaire sur le risque de chaque client repéré et son horizon de placement déclaré avant l’appel.</div>
<div class="checklist-item">Consigner chaque conversation, y compris la raison invoquée par le client pour toute demande de modification du plan.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Où en sont les choses après deux semaines volatiles<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir pris le temps de discuter aujourd’hui. Comme promis, voici la version courte. Depuis le 1er septembre, le TSX a connu 11 journées de variations d’environ un pour cent ou plus, et il est en baisse de 1,9&nbsp;% sur la période. Plusieurs de ces journées ont suivi une seule publication de données, et l’opinion du marché sur les hausses de taux des banques centrales s’est inversée à plusieurs reprises. Votre plan a été conçu pour tenir dans des périodes comme celle-ci.<br><br>
Les données sur l’inflation canadienne seront publiées le 19 octobre, et la Réserve fédérale comme la Banque du Canada rendront leur décision le 28 octobre. Je vous contacterai d’ici là. Entre-temps, n’hésitez pas à m’appeler si vos besoins de revenu ou votre horizon de placement ont changé.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Les investisseurs autonomes qui ont transigé autour du 9 ou du 14 octobre&nbsp;:</strong> une remontée sur de mauvaises nouvelles de l’emploi suivie d’une baisse sur de fortes nouvelles d’inflation est le genre de revirement qui laisse un investisseur autonome dans le doute, sans personne à qui demander conseil.</p>
<p><strong>Les investisseurs autonomes qui détiennent à la fois de l’énergie et des minières aurifères&nbsp;:</strong> l’écart du 14 octobre entre les deux a montré à quel point la position dépend d’une seule vision des taux.</p>
<p><strong>Les propriétaires d’entreprise avec des liquidités inutilisées&nbsp;:</strong> ceux qui attendent une décision de banque centrale avant d’investir sont exposés à l’habitude de lire chaque publication comme un verdict.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Le TSX a varié d’environ un pour cent ou plus lors de 11 séances depuis le 1er septembre et il est en baisse de 1,9&nbsp;% sur la période, et plusieurs de ces journées ont suivi une seule publication de données. J’appelle des gens pour leur demander comment ils s’en sortent.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Les six prochaines semaines comportent deux séries de catalyseurs prévus&nbsp;: l’inflation canadienne le 19 octobre et les deux décisions des banques centrales le 28 octobre. Un client potentiel qui gère seul son argent abordera chacune sans cadre pour décider si une seule donnée change quoi que ce soit. Les recherches sur les petits échantillons sont claires&nbsp;: elle ne change habituellement rien, et la première réaction est la moins fiable.</p>
<p>Le conseiller offre un processus à la place d’une réaction&nbsp;: un plan écrit, un horizon de placement déterminé et un appel prévu avant la publication. Voilà l’asymétrie. L’investisseur autonome a une opinion sur la prochaine publication. Le conseiller a un plan qui n’en dépend pas.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Comment les dernières semaines se comparent-elles à ce que vous attendiez de votre portefeuille&nbsp;?</div>
<div class="checklist-item">Avez-vous apporté des changements après le rapport sur l’emploi ou le rapport sur l’inflation&nbsp;?</div>
<div class="checklist-item">À quoi ressemblerait pour vous un mauvais résultat le 28 octobre, en dollars ou dans votre vie&nbsp;?</div>
<div class="checklist-item">Quand vous décidez d’acheter ou de vendre, sur quoi vous appuyez-vous, et jusqu’où remonte-t-il dans le temps&nbsp;?</div>
<div class="checklist-item">À qui parlez-vous quand un chiffre vous surprend&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> 11 grosses journées, et le TSX est en baisse de 1,9&nbsp;%<br><br>
Bonjour [Nom du client potentiel],<br><br>
Depuis le 1er septembre, le TSX a varié d’environ un pour cent ou plus lors de 11 séances et il est en baisse de 1,9&nbsp;% sur la période. Plusieurs de ces journées ont suivi un seul rapport sur l’emploi ou l’inflation. D’autres publications arriveront le 19 et le 28 octobre.<br><br>
Les recherches sur le comportement des investisseurs donnent à penser que les erreurs coûteuses viennent du fait de traiter chaque publication comme un verdict. Si cela peut vous être utile, je serais ravi de discuter de la façon de se préparer à ces dates. Auriez-vous 15 minutes cette semaine&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
