INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/10/15/deux-passages-par-jour-a-ormuz-contre-85-en-temps-normal-ce-que-signifie-un-brent-a-106-dollars-us-pour-un-portefeuille-canadien',
  'geo',
  'article',
  'Deux passages par jour à Ormuz contre 85 en temps normal : ce que signifie un Brent à 106 $ US pour un portefeuille canadien',
  'Des attaques iraniennes signalées contre deux autres navires le 14 octobre maintiennent la prime de risque pétrolière, et les bénéfices énergétiques canadiens l’encaissent.',
  '<ul>
<li><strong>Le détroit est pratiquement fermé,</strong><span> IMF PortWatch a recensé 2 passages le 11 octobre contre une moyenne d’avant la crise de 85 par jour.</span></li>
<li><strong>L’Iran aurait attaqué deux autres navires le 14 octobre,</strong><span> et le Brent a brièvement dépassé 107&nbsp;$&nbsp;US en début de séance avant de clôturer à 106,06&nbsp;$&nbsp;US.</span></li>
<li><strong>Les producteurs canadiens encaissent la prime,</strong><span> les bénéfices d’exploitation ont augmenté de 68&nbsp;% du T1 au T2 2026, selon Deloitte.</span></li>
<li><strong>L’offre ne peut pas réagir rapidement,</strong><span> le projet de pipeline Pacific Link vise une décision réglementaire d’ici le 1er septembre 2027, et Trans Mountain est plein.</span></li>
<li><strong>Le risque extrême va dans les deux sens,</strong><span> une réouverture ramènerait le WTI vers les 76,50&nbsp;$&nbsp;US que Deloitte suppose pour 2027, soit 20&nbsp;% sous la clôture du 14 octobre.</span></li>
</ul>',
  '<p>L’Iran aurait attaqué deux navires commerciaux dans le détroit d’Ormuz le 14 octobre en recourant à de nouvelles tactiques, selon Reuters, et le pétrole Brent a brièvement dépassé 107&nbsp;$&nbsp;US le baril en début de séance avant de clôturer à 106,06&nbsp;$&nbsp;US. IMF PortWatch a recensé deux passages dans le détroit le 11 octobre, contre une moyenne d’avant la crise de 85 par jour. Pour un investisseur canadien, la manchette compte moins que le mécanisme&nbsp;: la fermeture maintient une prime de risque dans le prix du pétrole, et cette prime atteint un portefeuille par les bénéfices du secteur de l’énergie, par l’inflation et par la trajectoire des taux d’intérêt en même temps.</p><h2>Comment la prime atteint les bénéfices canadiens</h2><p>Les producteurs canadiens sont preneurs de prix. Ils vendent un baril à un prix établi sur les marchés mondiaux, de sorte qu’un choc d’offre à des milliers de kilomètres se répercute directement sur leurs bénéfices d’exploitation. Deloitte rapporte que les bénéfices d’exploitation des producteurs de pétrole canadiens ont augmenté de 68&nbsp;% entre le premier et le deuxième trimestre de 2026.</p><p>Le West Texas Intermediate a clôturé à 95,09&nbsp;$&nbsp;US le 14 octobre, soit 38,7&nbsp;% au-dessus de sa clôture du 1er juillet à 68,58&nbsp;$&nbsp;US et au-dessus de la moyenne de 90&nbsp;$&nbsp;US que Deloitte prévoit pour 2026. Le FNB iShares S&amp;P/TSX Capped Energy a clôturé à 30,55&nbsp;$ le 14 octobre, en hausse de 6,1&nbsp;% par rapport à 28,79&nbsp;$ le 2 octobre et de 27,3&nbsp;% par rapport à 24,00&nbsp;$ le 2 juillet. Le détenteur d’un indice canadien général possède une partie de cette exposition par défaut. La même prime fait grimper les prix à la pompe, ce qui explique pourquoi Continuum Economics s’attend à ce que l’inflation globale canadienne se maintienne à 3,0&nbsp;% à la publication des données de septembre le 19 octobre.</p><p>Le West Texas Intermediate est passé de 68,58&nbsp;$&nbsp;US le 1er juillet à 95,09&nbsp;$&nbsp;US le 14 octobre, et il se situe maintenant au-dessus des deux hypothèses de prix de Deloitte, soit la moyenne de 90&nbsp;$&nbsp;US pour 2026 et celle de 76,50&nbsp;$&nbsp;US pour 2027.</p><div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">BRUT WTI, $&nbsp;US LE BARIL</span>
<span style="font-size:20px;font-weight:700;color:#111;">95,09&nbsp;$&nbsp;US</span>
<span style="font-size:13px;color:#2e7d32;">▲ 38,7&nbsp;% DEPUIS LE 1ER JUILL.</span>
<span style="font-size:11px;color:#888;margin-left:auto;">CLÔTURE QUOTIDIENNE &nbsp;|&nbsp; 1ER JUILL. AU 14 OCT. 2026</span>
</div>
<div style="padding:12px 14px 8px;">
