var v = [68.58,68.69,68.55,70.44,73.52,72.08,71.41,78.14,79.34,79.6,78.95,82.49,83.23,84.91,86.83,92.19,89.31,82.61,79.26,84.46,83.59,84.67,80.34,75.77,75.22,77.29,78.18,82.13,83.2,83.27,81.25,82.4,84.5,84.94,85.83,87.83,87.06,85.01,82.36,82.23,83.53,83.4,85.76,90.22,91.01,91.3,91.48,93.03,96.05,102.48,100.05,101.39,105.83,102.43,101.91,100.3,95.78,94.59,92.16,94.61,92.41,92.6,89.38,90.42,92.87,91.11,89.43,89.44,88.28,91.49,91.85,93.74,94.14,95.09];
