svg.appendChild(el("path", {d: d, fill: "none", stroke: "#1a3560", "stroke-width": 2, "stroke-linejoin": "round"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var ev = {lbl: "1 oct.", l1: "PACIFIC LINK", l2: "OLÉODUC ANNONCÉ"};
var ex = xp(idxOf(ev.lbl));
svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
var lastX = xp(n - 1), lastY = yp(last);
svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#1a3560"}));
var pillText = "95,09";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH - 8;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 3.5, 9, 700, "#111111", "middle"));
var w = Math.max(ev.l1.length, ev.l2.length) * 7 * 0.68;
var nearRight = (ex + w + 3) > (margin.left + PW);
var anchor = nearRight ? "end" : "start";
var dx = nearRight ? -4 : 3;
var y0 = MT + 14;
var hx = nearRight ? (ex + dx - w - 2) : (ex + dx - 2);
svg.appendChild(el("rect", {x: hx, y: y0 - 8, width: w + 4, height: 20, fill: "#ffffff", "fill-opacity": 0.92}));
