svg.appendChild(tx(ev.l2, ex + dx, y0 + 9, 7, 700, "#1a3560", anchor));
refs.forEach(function(r){
  if (Math.abs(r.val - last) / last < 0.03) return;
  var ry = yp(r.val);
  var lx = r.anchor === "end" ? margin.left + PW - 4 : margin.left + 10;
