function idxOf(lbl){ for (var i = 0; i < n; i++) { if (dates[i] === lbl) return i; } return 0; }
var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("viewBox", "0 0 680 300");
svg.setAttribute("width", "100%");
var t, ticks = [];
for (t = yMin; t <= yMax; t += 5) { ticks.push(t); }
ticks.forEach(function(tk){
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(tk), y2: yp(tk), stroke: "#ececec", "stroke-width": 0.5}));
});
var refY = yp(base);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#7a3030", "stroke-width": 1, "stroke-dasharray": "3,3"}));
series.forEach(function(s){
  var d = "";
  s.v.forEach(function(val, i){ d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(val).toFixed(1) + " "; });
  svg.appendChild(el("path", {d: d, fill: "none", stroke: s.color, "stroke-width": s.w, "stroke-linejoin": "round"}));
});
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var events = [
  {lbl: "16 sept.", l1: "16 SEPT. HAUSSE", l2: "3,75\u00a0% À 4,00\u00a0%", val: 85.5},
  {lbl: "14 oct.", l1: "14 OCT. IPC US FORT", l2: "XGD -4,2\u00a0%", val: 82}
];
events.forEach(function(ev){
  var ex = xp(idxOf(ev.lbl));
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: MT, y2: MT + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-width": 1, "stroke-dasharray": "2,3"}));
});
var lastX = xp(n - 1);
series.forEach(function(s){
  svg.appendChild(el("circle", {cx: lastX, cy: yp(s.v[n - 1]), r: 3, fill: s.color}));
});
var xeg = series[3];
var lastY = yp(xeg.v[n - 1]);
var pillText = "+7,5\u00a0%";
var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
var pillY = lastY - pillH - 6;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(tx(pillText, pillX + pillW / 2, pillY + pillH / 2 + 3.5, 9, 700, "#111111", "middle"));
events.forEach(function(ev){
  var ex = xp(idxOf(ev.lbl));
  var w = Math.max(ev.l1.length, ev.l2.length) * 7 * 0.68;
  var nearRight = (ex + w + 3) > (margin.left + PW);
  var anchor = nearRight ? "end" : "start";
  var dx = nearRight ? -4 : 3;
  var y0 = yp(ev.val);
  var hx = nearRight ? (ex + dx - w - 2) : (ex + dx - 2);
  svg.appendChild(el("rect", {x: hx, y: y0 - 8, width: w + 4, height: 20, fill: "#ffffff", "fill-opacity": 0.92}));
  svg.appendChild(tx(ev.l1, ex + dx, y0, 7, 700, "#1a3560", anchor));
  svg.appendChild(tx(ev.l2, ex + dx, y0 + 9, 7, 700, "#1a3560", anchor));
});
series.forEach(function(s){
  svg.appendChild(tx(s.name, lastX - 5, yp(s.v[n - 1]) + s.off, 7.5, 700, "#666666", "end"));
});
ticks.forEach(function(tk){
  svg.appendChild(tx(String(tk), margin.left - 6, yp(tk) + 3, 8.5, 400, "#aaaaaa", "end"));
});
["31 août", "8 sept.", "16 sept.", "23 sept.", "1 oct.", "14 oct."].forEach(function(l){
  var i = idxOf(l);
  var a = (i === n - 1) ? "end" : "middle";
  svg.appendChild(tx(dates[i], xp(i), MT + PH + 14, 8, 400, "#999999", a));
});
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: clôtures quotidiennes de Yahoo Finance pour l’indice composé S&amp;P/TSX (^GSPTSE), XEG.TO, XGD.TO et XFN.TO, 31 août au 14 octobre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">XEG est le FNB iShares S&amp;P/TSX Capped Energy, XGD le FNB iShares S&amp;P/TSX Global Gold et XFN le FNB iShares S&amp;P/TSX Capped Financials. Chaque série est rebasée à 100 à sa clôture du 31 août, représentée par la ligne en pointillé, et les séances sans clôture dans les quatre séries sont exclues.</p><h2>Le 14 octobre était une journée de taux</h2><p>La séance la plus récente montre l’écart dans toute sa force. Les prix à la consommation américains publiés le 14 octobre ont dépassé les attentes, avec une inflation globale de 3,7&nbsp;% et une hausse mensuelle de base de 0,3&nbsp;% contre 0,2&nbsp;% attendu, et l’indice composé S&amp;P/TSX a reculé de 1,1&nbsp;%, soit environ 400 points, à 35&nbsp;584,46. Le S&amp;P 500 a reculé de 1,1&nbsp;% à 7&nbsp;718,94 et le VIX est monté à 16,87 contre 15,27.</p><p>À l’intérieur de l’indice canadien, les dégâts étaient concentrés. XGD a reculé de 4,2&nbsp;% et l’or de 1,7&nbsp;%. XFN a reculé de 0,5&nbsp;%. XEG a clôturé inchangé à 30,55&nbsp;$ alors que le prix du pétrole se maintenait près de ses sommets, le Brent clôturant à 106,06&nbsp;$&nbsp;US. Les minières aurifères ont bougé environ 2,5 fois plus que le métal, qui a reculé de 1,7&nbsp;%. Le rendement à 10 ans a clôturé à 5,19&nbsp;%, soit 3 points de base sous celui de la veille, de sorte que l’écart reflète une réévaluation de la trajectoire de la Fed et non un mouvement de l’extrémité longue seule. Une journée où l’indice a reculé de 1,1&nbsp;% comportait donc un recul de 4,2&nbsp;% dans un secteur et aucun recul dans un autre. Quiconque ne lisait que l’indice a vu une vente massive généralisée. Le détail par secteur montre une vente massive des actifs les plus sensibles au rendement américain.</p><h2>Ce qui décidera de la prochaine étape</h2><p>Les services financiers n’ont nulle part progressé, ce qui compte pour ce que l’indice vous dit. XFN recule de 1,7&nbsp;% depuis le 31 août, en ligne avec le recul de 1,9&nbsp;% du TSX, de sorte que le mouvement n’est pas une histoire de banques. C’est le résultat net d’un gain de 7,5&nbsp;% dans l’énergie et d’une perte de 13,1&nbsp;% dans l’or.</p><p>Deux dates mettront l’écart à l’épreuve. Statistique Canada publie l’IPC de septembre le 19 octobre, et Continuum Economics s’attend à ce que l’inflation globale se maintienne à 3,0&nbsp;%. La Fed et la Banque du Canada rendent toutes deux leur décision le 28 octobre. Les probabilités d’une hausse de la Fed se situaient entre 42&nbsp;% et 50&nbsp;% environ le 14 octobre selon la source, tandis que LSEG évaluait à environ 25&nbsp;% les probabilités d’une hausse de la Banque du Canada après la perte d’environ 68&nbsp;000 emplois en septembre.</p><p>Il en résulte que l’écart est la position. Une donnée élevée et une hausse prolongeraient la tendance, l’énergie tenant bon et les minières aurifères restant sous pression. Une donnée faible soulagerait d’abord le canal des taux, ce qui aiderait les minières aurifères avant de faire quoi que ce soit pour l’énergie. Une réouverture du détroit d’Ormuz frapperait directement la composante énergie.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui détiennent des minières aurifères voient une perte à deux chiffres alors que les manchettes parlent d’un monde au bord du gouffre, et ils demandent pourquoi l’or baisse quand les nouvelles sont mauvaises. Les clients qui détiennent de l’énergie voient des gains et se demandent s’il faut les encaisser. Les clients qui détiennent l’indice voient un petit recul et ne ressentent rien, sans savoir ce qu’il y a en dessous.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">L’indice canadien recule d’environ 2&nbsp;% depuis la fin d’août, mais ce chiffre cache un écart important. L’énergie gagne 7,5&nbsp;% et les minières aurifères perdent 13,1&nbsp;%. Les deux réagissent à la même chose&nbsp;: le pétrole est élevé, l’inflation est élevée, les taux d’intérêt montent et le rendement américain à 10 ans est de 5,19&nbsp;%. L’or ne rapporte aucun revenu, de sorte que la hausse des rendements joue contre lui. C’est pourquoi l’or a baissé malgré les mauvaises nouvelles dans le monde. Je ne peux pas vous dire dans quel sens cela ira. L’inflation canadienne sera publiée le 19 octobre et les deux banques centrales rendront leur décision le 28 octobre. Ce que je peux faire, c’est vous montrer quelle part de votre portefeuille se trouve de chaque côté de cet écart, afin que nous décidions si c’est l’équilibre que vous voulez.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients ayant des placements concentrés dans les minières aurifères ou les métaux précieux, qui ont subi la perte.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients qui détiennent l’indice canadien général, où les gains de l’énergie et les pertes de l’or se compensent en grande partie.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients dont les gains en énergie dépassent la pondération cible et qui souhaiteront peut-être rééquilibrer, et les clients disposant de liquidités qui voient des prix plus bas dans les minières aurifères.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Repérer les clients dont plus de 10&nbsp;% du portefeuille est investi dans des minières aurifères ou des fonds de métaux précieux.</div>
<div class="checklist-item">Repérer les clients dont la pondération en énergie s’est écartée à la hausse de la cible depuis le 31 août.</div>
<div class="checklist-item">Examiner la situation fiscale de toute vente de rééquilibrage avant de la recommander.</div>
<div class="checklist-item">Inscrire au calendrier les contacts du 19 et du 28 octobre, avant la publication de l’IPC et les décisions des banques centrales.</div>
<div class="checklist-item">Consigner chaque conversation, y compris ce qu’on a dit au client sur la sensibilité de l’or aux taux.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Ce qui se cache sous le recul du TSX<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir discuté avec moi aujourd’hui. En résumé&nbsp;: l’indice canadien recule d’environ 2&nbsp;% depuis le 31 août, l’énergie gagnant 7,5&nbsp;% et les minières aurifères perdant 13,1&nbsp;%. Les deux mouvements s’expliquent par le pétrole, l’inflation et le rendement américain à 10 ans, qui est de 5,19&nbsp;%.<br><br>
Je vous enverrai avant le 19 octobre, date de publication de l’inflation canadienne, une ventilation de la part de votre portefeuille dans chaque secteur. N’hésitez pas à m’appeler si vous souhaitez en discuter plus tôt.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Les investisseurs autonomes qui ont acheté des minières aurifères comme valeur refuge&nbsp;:</strong> le secteur recule de 13,1&nbsp;% depuis le 31 août et la thèse n’a pas fonctionné dans un marché de taux en hausse.</p>
<p><strong>Les investisseurs indiciels qui croient le TSX diversifié&nbsp;:</strong> un recul de 1,9&nbsp;% cache un écart de 20,6 points entre deux secteurs.</p>
<p><strong>Les investisseurs qui ont couru après l’énergie le mois dernier&nbsp;:</strong> ils ont un gain et aucun plan en cas de réouverture du détroit d’Ormuz.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Le TSX recule d’environ 2&nbsp;% depuis la fin d’août, mais l’énergie gagne 7,5&nbsp;% et les minières aurifères perdent 13,1&nbsp;%. J’appelle des gens pour leur demander s’ils savent de quel côté de cet écart se trouve leur portefeuille.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>L’indice canadien semble calme en surface alors que deux grands secteurs évoluent en sens contraire selon la même variable, le rendement américain. Un client potentiel qui ne détient qu’un des deux côtés porte toute l’oscillation.</p>
<p>Le conseiller offre un examen de l’exposition sectorielle avant deux événements prévus, l’IPC canadien le 19 octobre et les décisions des banques centrales le 28 octobre, afin que les décisions soient prises avant la manchette et non après.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Quelle part de votre portefeuille est investie dans les minières aurifères ou l’énergie, directement ou par des fonds&nbsp;?</div>
<div class="checklist-item">Pourquoi avez-vous acheté de l’or, et cette raison a-t-elle changé depuis la variation du rendement&nbsp;?</div>
<div class="checklist-item">Que feriez-vous si l’énergie redonnait le gain depuis août&nbsp;?</div>
<div class="checklist-item">Comment décidez-vous du moment de rééquilibrer&nbsp;?</div>
<div class="checklist-item">Qui examine ces positions avec vous en ce moment&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Le TSX recule de 2&nbsp;%, mais un secteur recule de 13&nbsp;%<br><br>
